SELECT p.player_name, pa.overall_rating
FROM Player_Attributes pa JOIN Player p ON p.player_api_id = pa.player_api_id
ORDER BY pa.overall_rating DESC LIMIT 5;

SELECT p.player_name, pa.strength
FROM Player_Attributes pa JOIN Player p ON p.player_api_id = pa.player_api_id
ORDER BY pa.strength DESC LIMIT 5;
